    try{
      const response=await fetch(`fte_api.php?${params}`,{credentials:'same-origin'});
      const payload=await response.json();
      if(!payload.ok){
        const reference=payload.reference?` Referencia: ${payload.reference}.`:'';
        throw new Error(`${payload.error||'No fue posible calcular el mes.'}${reference}`);
      }
      render(payload.data||{});
    }catch(error){
      errorBox.textContent=error.message||'No fue posible calcular el mes.';
      errorBox.classList.remove('d-none');
    }finally{
      window.clearInterval(elapsedTimer);
      monthlyElapsed.textContent=`Tiempo real de la última consulta: ${((performance.now()-startedAt)/1000).toFixed(1)} segundos.`;
      loading.classList.add('d-none');
    }
  });
  conceptDetailClose.addEventListener('click',()=>{if(typeof conceptDetailDialog.close==='function')conceptDetailDialog.close();else conceptDetailDialog.removeAttribute('open')});
  conceptDetailDialog.addEventListener('click',event=>{if(event.target===conceptDetailDialog){if(typeof conceptDetailDialog.close==='function')conceptDetailDialog.close();else conceptDetailDialog.removeAttribute('open')}});
  loadCecos();
})();
</script>
</body></html>
